(() => {
 const BILIBILI_ENABLED=false;
 const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const renderScript=p=>{
  const blocks=window.projectDocuments?.[p.documentKey||(p.id==='plumas'?'Plumas-羽毛制作者':p.title)];
  const content=blocks?blocks.map((b,i)=>b.kind==='table'?`<table class="script-table"><thead><tr>${(b.rows[0]||[]).map(c=>`<th scope="col" colspan="${c.span}">${esc(c.text)}</th>`).join('')}</tr></thead><tbody>${b.rows.slice(1).map(row=>`<tr>${row.map(c=>`<td colspan="${c.span}">${esc(c.text)}</td>`).join('')}</tr>`).join('')}</tbody></table>`:b.kind==='heading'||i===0?`<h4 class="doc-heading">${esc(b.text)}</h4>`:`<p class="doc-paragraph">${esc(b.text)}</p>`).join(''):p.media.script.map(t=>`<p class="doc-paragraph">${esc(t)}</p>`).join('');
  return `<div class="script-toolbar"><span>保留表格结构，可左右滚动阅读</span><div role="group" aria-label="剧本字号"><button type="button" data-script-font="12" aria-pressed="false">小字</button><button type="button" data-script-font="13" aria-pressed="true">默认</button><button type="button" data-script-font="15" aria-pressed="false">大字</button></div></div><div class="script-text script-reader" tabindex="0" role="region" aria-label="剧本与分镜文字，可横向滚动">${content}</div>`;
 };
 const plumas={id:'plumas',type:'video',category:'short',tag:'短片',title:'Plumas · 羽毛制作者',bvid:'BV1ghyWzLEqG',cover:'assets/projects/plumas/cover.jpg',coverLabel:'作品封面',synopsis:'男孩把公鸡 Plumas 当作最好的朋友，父亲却要求它上场斗鸡。母亲为孩子争取童年的自由，让这对伙伴继续在游戏、电影与冒险幻想中相伴。',media:window.plumasMedia};
 window.portfolioProjects=[...window.localProjects,...window.designProjects];
 for(const p of window.portfolioProjects){if(p.id==='plumas')p.media=window.plumasMedia;}
 projects.splice(0,projects.length,...window.portfolioProjects);
 const watchControl=p=>p.externalVideo?`<a class="button dark plant-control plant-watch" href="${esc(p.externalVideo.url)}" target="_blank" rel="noopener noreferrer">前往网盘观看 ↗</a>`:`<button class="button dark plant-control plant-watch" data-project-open="${p.id}" data-mode="watch">观看成片</button>`;
 art=p=>p.collection?`<button type="button" class="project-art plumas-cover cover-open collection-cover" data-project-open="${p.id}" data-mode="design" aria-label="${esc('查看设计：'+p.title)}"><div class="collection-preview" data-kind="${p.previewKind}">${p.preview.map(x=>`<img src="${esc(x.src)}" width="${x.width}" height="${x.height}" alt="" loading="lazy" decoding="async">`).join('')}</div><span class="cover-action" aria-hidden="true">浏览作品</span></button>`:p.externalVideo?`<a class="project-art plumas-cover cover-open" href="${esc(p.externalVideo.url)}" target="_blank" rel="noopener noreferrer" aria-label="${esc('前往百度网盘观看：'+p.title)}"><img src="${esc(p.cover)}" alt="${esc(p.title)}" loading="lazy"><span class="cover-action" aria-hidden="true">前往网盘观看 ↗</span></a>`:`<button type="button" class="project-art plumas-cover cover-open" data-project-open="${p.id}" data-mode="${p.type==='design'?'design':'watch'}" aria-label="${esc((p.type==='design'?'查看设计：':'播放：')+p.title)}"><img src="${esc(p.cover)}" alt="${esc(p.title+' '+p.coverLabel)}" loading="lazy"><span class="cover-action" aria-hidden="true">${p.type==='design'?'查看设计':'▶ 播放成片'}</span></button>`;
 renderGrid=(id,type='all',cat='all')=>{
  const list=projects.filter(p=>(type==='all'||p.type===type)&&(cat==='all'||p.category===cat||p.categories?.includes(cat)||cat==='game'&&p.category==='feed'||cat==='commercial'&&['tvc','seeding','feed'].includes(p.category)));
  document.getElementById(id).innerHTML=list.map(p=>p.type==='design'?`<article class="project-card real-project design-card">${art(p)}<div class="project-info"><div><h3>${esc(p.title)}</h3><p>VISUAL DESIGN · ${esc(p.tag)} · ${p.pageCount} ${p.page?'张':'页'}</p></div></div><p class="card-synopsis">${esc(p.synopsis)}</p><div class="project-actions"><button class="button dark plant-control plant-process" data-project-open="${p.id}" data-mode="design">查看设计</button><a class="button" href="${esc(p.page||p.pdf)}" ${p.page?'':'target="_blank" rel="noopener"'}>${p.collection?'浏览全部作品':p.page?'查看完整方案':'阅读项目 PDF'}</a></div></article>`:`<article class="project-card real-project ${p.category==='film'?'landscape-card':(p.portrait?'portrait-card':'landscape-card')}">${art(p)}<div class="project-info"><div><h3>${esc(p.title)}</h3><p>AI VIDEO · ${esc(p.tag)}</p></div></div><p class="card-synopsis">${esc(p.synopsis)}</p><div class="project-actions">${watchControl(p)}<button class="button plant-control plant-process" data-project-open="${p.id}" data-mode="process">查看制作过程</button></div></article>`).join('')||'<p class="empty">此分类暂未添加作品。<br>素材整理完成后将在这里展示。</p>';
 };
 const lightbox=document.createElement('dialog');lightbox.className='asset-lightbox';lightbox.setAttribute('aria-label','资产图片放大');lightbox.innerHTML='<button type="button" class="close" aria-label="关闭图片">×</button><img alt=""><p></p>';document.body.append(lightbox);
 lightbox.querySelector('button').onclick=()=>lightbox.close();lightbox.onclick=e=>{if(e.target===lightbox)lightbox.close()};
 const zoom=document.createElement('button');zoom.type='button';zoom.className='image-zoom';zoom.textContent='放大查看';lightbox.append(zoom);zoom.onclick=()=>{const active=lightbox.classList.toggle('is-zoomed');zoom.textContent=active?'适应屏幕':'放大查看';};
 let album=[],albumIndex=0;
 const previous=document.createElement('button'),next=document.createElement('button'),counter=document.createElement('span');
 previous.type=next.type='button';previous.className='album-prev';next.className='album-next';previous.textContent='‹';next.textContent='›';previous.setAttribute('aria-label','上一张图片');next.setAttribute('aria-label','下一张图片');counter.className='album-count';counter.setAttribute('aria-live','polite');lightbox.append(previous,next,counter);
 function showAlbumImage(){const item=album[albumIndex];if(!item)return;lightbox.classList.remove('is-zoomed');zoom.textContent='放大查看';lightbox.querySelector('img').src=item.src;lightbox.querySelector('img').alt=item.title;lightbox.querySelector('p').textContent=item.title;counter.textContent=(albumIndex+1)+' / '+album.length;previous.disabled=albumIndex===0;next.disabled=albumIndex===album.length-1;lightbox.scrollTop=0;lightbox.scrollLeft=0;}
 function stepAlbum(delta){const i=albumIndex+delta;if(i<0||i>=album.length)return;albumIndex=i;showAlbumImage();}
 previous.onclick=()=>stepAlbum(-1);next.onclick=()=>stepAlbum(1);
 lightbox.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'||e.key==='ArrowRight'){e.preventDefault();e.stopPropagation();stepAlbum(e.key==='ArrowLeft'?-1:1);}});
 let touchX;lightbox.addEventListener('touchstart',e=>{if(!lightbox.classList.contains('is-zoomed'))touchX=e.changedTouches[0].clientX;},{passive:true});lightbox.addEventListener('touchend',e=>{if(touchX===undefined)return;const dx=e.changedTouches[0].clientX-touchX;touchX=undefined;if(Math.abs(dx)>60)stepAlbum(dx<0?1:-1);},{passive:true});
 const renderPlayer=p=>p.externalVideo?`<section id="finished-film"><h3>成片</h3><a href="${esc(p.externalVideo.url)}" target="_blank" rel="noopener noreferrer"><img src="${esc(p.cover)}" alt="${esc(p.title)}，点击前往百度网盘" style="width:100%;max-height:55vh;object-fit:contain"></a><div class="project-actions">${watchControl(p)}<button class="button" type="button" data-copy-code="${esc(p.externalVideo.code)}">复制提取码：${esc(p.externalVideo.code)}</button></div><p>在新标签页打开百度网盘，链接已包含提取码。</p></section>`:`<section id="finished-film"><h3>成片</h3><video class="local-player ${p.portrait?'is-portrait':''}" controls playsinline preload="metadata" poster="${esc(p.cover)}" src="${esc(p.video)}" aria-label="${esc(p.title)} 成片"></video><p class="playback-message" hidden>视频暂时无法加载，可以直接打开视频文件观看。</p><div class="project-actions"><a class="video-download" href="${esc(p.video)}" target="_blank" rel="noopener">打开视频文件</a>${BILIBILI_ENABLED&&p.bvid?`<a class="video-download" href="https://www.bilibili.com/video/${p.bvid}/" target="_blank" rel="noopener noreferrer">在 Bilibili 观看</a>`:''}</div></section>`;
 const gallery=items=>items.map(x=>`<button class="asset-thumb" data-full="${esc(x.src)}" data-caption="${esc(x.title)}"><img src="${esc(x.src)}" alt="${esc(x.title)}" loading="lazy" decoding="async"><span>${esc(x.title)}</span></button>`).join('');
 const renderDesign=p=>{
  if(p.page){location.href=p.page;return;}
  dialog.classList.add('design-dialog');
  dialog.setAttribute('aria-label',p.title);
  document.getElementById('dialog-content').innerHTML=`<span class="chip">VISUAL DESIGN / ${esc(p.tag)}</span><h2>${esc(p.title)}</h2><p class="design-intro">${esc(p.synopsis)}</p><div class="design-hero"><img src="${esc(p.cover)}" alt="${esc(p.title)}主视觉"></div><div class="project-actions"><a class="button dark" href="${esc(p.pdf)}" target="_blank" rel="noopener">阅读项目 PDF · ${p.pageCount} 页</a><a class="button" href="${esc(p.pdf)}" download>下载项目 PDF</a><a class="text-link" href="assets/design/brand-collection-2026.pdf?v=20261124-sync10" target="_blank" rel="noopener">完整合集 · 40 页</a></div><nav class="design-section-nav" aria-label="项目内容分组">${p.sections.map((s,i)=>`<button type="button" data-design-section="design-section-${i}">${esc(s.title)}</button>`).join('')}</nav><p class="design-read-hint">按主题浏览，点击页面可放大阅读；PDF 保留完整原页内容。</p>${p.sections.map((s,i)=>`<section class="design-section" id="design-section-${i}"><h3>${esc(s.title)}</h3><div class="design-page-grid">${gallery(s.items)}</div></section>`).join('')}`;
  dialog.querySelectorAll('[data-design-section]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.designSection).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'}));
  dialog.showModal();dialog.scrollTop=0;
 };
 document.addEventListener('click',e=>{
  const copy=e.target.closest('[data-copy-code]');if(copy){navigator.clipboard.writeText(copy.dataset.copyCode).then(()=>copy.textContent='提取码已复制').catch(()=>copy.textContent='提取码：'+copy.dataset.copyCode);return;}
  const image=e.target.closest('[data-full]');if(image){album=[...dialog.querySelectorAll('[data-full]')].map(b=>({src:b.dataset.full,title:b.dataset.caption}));albumIndex=[...dialog.querySelectorAll('[data-full]')].indexOf(image);lightbox.classList.toggle('design-lightbox',dialog.classList.contains('design-dialog'));showAlbumImage();lightbox.showModal();return;}
  const font=e.target.closest('[data-script-font]');if(font){const details=font.closest('details');details.querySelector('.script-reader').style.setProperty('--script-font',font.dataset.scriptFont+'px');details.querySelectorAll('[data-script-font]').forEach(b=>b.setAttribute('aria-pressed',String(b===font)));return;}
  const trigger=e.target.closest('[data-project-open]');if(!trigger)return;
  const p=projects.find(p=>p.id===trigger.dataset.projectOpen);if(p.type==='design'){renderDesign(p);return;}dialog.classList.remove('design-dialog');const m=p.media;const groups=[...new Set(m.assets.map(x=>x.group))];
  dialog.setAttribute('aria-label',p.title);
  document.getElementById('dialog-content').innerHTML=`<span class="chip">VIDEO PROJECT / ${esc(p.tag)}</span><h2>${esc(p.title)}</h2><div class="project-actions"><button class="button dark plant-control plant-watch" data-section="finished-film">观看成片</button><button class="button plant-control plant-process" data-section="making-of">查看制作过程</button></div><section class="story-synopsis" aria-labelledby="synopsis-title"><span class="chip">${['tvc','seeding','feed'].includes(p.category)?'THE CONCEPT':'THE STORY'}</span><h3 id="synopsis-title">${['tvc','seeding','feed'].includes(p.category)?'内容梗概':'故事梗概'}</h3><p>${esc(p.synopsis)}</p></section>${renderPlayer(p)}<section class="responsibilities"><h3>个人职责</h3>${p.responsibilitiesStatus?`<p class="content-source-note">${esc(p.responsibilitiesStatus)}</p>`:''}<p>${esc(p.responsibilities||'待补充确认。')}</p></section><section id="making-of"><h3>制作过程</h3><p>制作资产共 ${m.assets.length} 张。点击分类展开，点击图片放大。</p>${groups.map((g,i)=>`<details class="asset-branch" ${i===0?'open':''}><summary>${esc(g.replace(/^\d+_/,''))}<span>${m.assets.filter(x=>x.group===g).length} 张</span></summary><div class="asset-grid">${gallery(m.assets.filter(x=>x.group===g))}</div></details>`).join('')}<h3>${esc(p.scriptTitle||'剧本与分镜')}</h3>${p.scriptNote?`<p class="content-source-note">${esc(p.scriptNote)}</p>`:''}<div class="asset-grid">${gallery(m.storyboard)}</div>${window.projectDocuments?.[p.documentKey]||m.script?.length?`<details><summary>阅读剧本与分镜文字</summary>${renderScript(p)}</details>`:'<p>暂未提供剧本与分镜文档。</p>'}</section>`;
  const player=dialog.querySelector('.local-player');
  if(player){player.addEventListener('click',e=>{const r=player.getBoundingClientRect();if(e.clientY>r.bottom-48)return;e.preventDefault();if(player.paused)player.play().catch(()=>{});else player.pause();});
  player.addEventListener('error',()=>{dialog.querySelector('.playback-message').hidden=false});
  player.addEventListener('loadedmetadata',()=>player.classList.toggle('is-portrait',player.videoHeight>player.videoWidth));}
  function selectVideoView(section){
   const process=section==='making-of';
   dialog.dataset.view=process?'process':'watch';
   dialog.querySelector('#finished-film').hidden=process;
   dialog.querySelector('.story-synopsis').hidden=process;
   dialog.querySelector('.responsibilities').hidden=!process;
   dialog.querySelector('#making-of').hidden=!process;
   dialog.querySelectorAll('[data-section]').forEach(b=>{const selected=b.dataset.section===section;b.setAttribute('aria-pressed',String(selected));b.setAttribute('aria-controls',b.dataset.section);b.classList.toggle('dark',selected);});
   dialog.scrollTop=0;
   if(player){if(process)player.pause();else player.play().catch(()=>{});}
  }
  dialog.querySelectorAll('[data-section]').forEach(b=>b.onclick=()=>selectVideoView(b.dataset.section));
  selectVideoView(trigger.dataset.mode==='process'?'making-of':'finished-film');
  dialog.showModal();dialog.scrollTop=0;
 });
 dialog.addEventListener('close',()=>{dialog.classList.remove('design-dialog');const player=dialog.querySelector('video');if(player){player.pause();player.removeAttribute('src');player.load();}});
 renderGrid('home-grid');if(document.getElementById('all-grid'))renderGrid('all-grid');
})();

